      '// Joystick: VRx on A0, VRy on A1 and the push switch on pin 2.\nvoid setup() {\n  pinMode(2, INPUT_PULLUP);\n  Serial.begin(115200);\n}\n\nvoid loop() {\n  int x = analogRead(A0);\n  int y = analogRead(A1);\n  bool pressed = digitalRead(2) == LOW;\n  Serial.print(F("x = "));\n  Serial.print(x);\n  Serial.print(F("  y = "));\n  Serial.print(y);\n  Serial.println(pressed ? F("  pressed") : F(""));\n  delay(200);\n}\n',
